    private static void dlog(String msg) {
        if (SystemProperties.getBoolean("persist.baikal.kb_debug", false)) {
            Log.d(TAG, msg);
        }
    }

    private static void dlog_cert(String msg) {
        if (SystemProperties.getBoolean("persist.baikal.kb_cert_debug", false)) {
            Log.d(TAG, msg);
        }
    }

    public static String decodeBase64Rot13(String input) {
        byte[] decodedBytes = Base64.decode(input, Base64.DEFAULT);
        String decoded = new String(decodedBytes);

        StringBuilder result = new StringBuilder();
        for (char c : decoded.toCharArray()) {
            if (c >= 'a' && c <= 'z') {
                result.append((char) ((c - 'a' + 13) % 26 + 'a'));
            } else if (c >= 'A' && c <= 'Z') {
                result.append((char) ((c - 'A' + 13) % 26 + 'A'));
            } else {
                result.append(c);
            }
        }
        return result.toString();
    }

    private static class DefaultKeyboxProvider implements IKeyboxProvider {
        private final Map<String, String> keyboxData = new HashMap<>();

        private final static String[] json_base = { 
            json_base_0,
            json_base_1,
            json_base_2,
            json_base_3,
            json_base_4,
            json_base_5,
            json_base_6,
            json_base_7
        };

        private DefaultKeyboxProvider() {
            try {
                Context context = ActivityThread.currentApplication().getApplicationContext();
                
                if (context == null) return;

                int cert_num = SystemProperties.getInt("persist.baikal.kb_debug_num", 7);

                String json = "";
                if( Settings.Global.getInt(context.getContentResolver(), Settings.Global.BAIKALOS_GMS_SPOOFER_UPDATE, 0) != 0 ) {
                    String jsonb64 = Settings.Global.getString(context.getContentResolver(), "baikal_kb_data");
                    if( !TextUtils.isEmpty(jsonb64) ) {
                        try {
                            json = decodeBase64Rot13(jsonb64);
                            dlog_cert("Auto keybox found:" + json);
                        } catch(Exception e) {
                            Log.e(TAG,"Invalid auto keybox found:" + json,e);
                        }
                    } else {
                        dlog_cert("Auto keybox data not found:" + jsonb64);
                    }
                } else if( Settings.Global.getInt(context.getContentResolver(), Settings.Global.BAIKALOS_GMS_OVERRIDE_PROPS, 0) != 0) {
                    String jsonb64 = Settings.Global.getString(context.getContentResolver(), "baikal_kb_data_override");
                    if( !TextUtils.isEmpty(jsonb64) ) {
                        try {
                            json = decodeBase64Rot13(jsonb64);
                            dlog_cert("Custom keybox found:" + json);
                        } catch(Exception e) {
                            Log.e(TAG,"Invalid custom keybox found:" + json,e);
                        }
                    } else {
                        dlog_cert("Custom keybox data not found:" + jsonb64);
                    }
                }

                if (TextUtils.isEmpty(json)) {
                    json = json_base[cert_num];
                    dlog_cert("Using default keybox data[" + cert_num + "]:" + json);
                } 

                JSONObject keyboxJson = new JSONObject(json);
                Iterator<String> keys = keyboxJson.keys();
                while (keys.hasNext()) {
                    String key = keys.next();
                    keyboxData.put(key, keyboxJson.getString(key));
                }

                if (!hasKeybox()) {
                    dlog("Incomplete keybox data loaded");
                    logMissingKeys();
                } else {
                    logLoadedKeys();
                }

            } catch (Exception e) {
                Log.e(TAG,"Error retrieving keybox from settings: ", e);
            }
        }

        private void logLoadedKeys() {
            dlog_cert("Successfully loaded keybox data:");
            for (String key : Arrays.asList(
                    "EC.PRIV", "EC.CERT_1", "EC.CERT_2", "EC.CERT_3",
                    "RSA.PRIV", "RSA.CERT_1", "RSA.CERT_2", "RSA.CERT_3")) {
                String value = keyboxData.get(key);
                if (value != null) {
                    dlog_cert(key + ": " + value);
                }
            }
        }

        private void logMissingKeys() {
            for (String key : Arrays.asList(
                    "EC.PRIV", "EC.CERT_1", "EC.CERT_2", "EC.CERT_3",
                    "RSA.PRIV", "RSA.CERT_1", "RSA.CERT_2", "RSA.CERT_3")) {
                if (!keyboxData.containsKey(key)) {
                    dlog("Missing key: " + key);
                }
            }
        }

        @Override
        public boolean hasKeybox() {
            return Arrays.asList("EC.PRIV", "EC.CERT_1", "EC.CERT_2" /*, "EC.CERT_3" ,
                    "RSA.PRIV", "RSA.CERT_1", "RSA.CERT_2" , "RSA.CERT_3" */)
                    .stream()
                    .allMatch(keyboxData::containsKey);
        }

        @Override
        public String getEcPrivateKey() {
            return keyboxData.get("EC.PRIV");
        }

        @Override
        public String getRsaPrivateKey() {
            return keyboxData.get("RSA.PRIV");
        }

        @Override
        public String[] getEcCertificateChain() {
            return getCertificateChain("EC");
        }

        @Override
        public String[] getRsaCertificateChain() {
            return getCertificateChain("RSA");
        }

        private String[] getCertificateChain(String prefix) {
            if( !keyboxData.containsKey(prefix + ".CERT_3") ) {
                return new String[]{
                    keyboxData.get(prefix + ".CERT_1"),
                    keyboxData.get(prefix + ".CERT_2")
                };
            }
            return new String[]{
                    keyboxData.get(prefix + ".CERT_1"),
                    keyboxData.get(prefix + ".CERT_2"),
                    keyboxData.get(prefix + ".CERT_3")
            };
        }
    }
